lib/config/inertia.dart<pre><code>import 'package:dox_core/dox_core.dart';
import 'package:dox_inertia/dox_inertia.dart';

InertiaConfig inertiaConfig = InertiaConfig(
  entryPoints: &lt;String&gt;['resources/js/app.jsx'],

  /// load the scripts from the Vite dev server, only in dev
  devServerUrl: Env.get&lt;String&gt;('APP_ENV') == 'development'
      ? 'http://localhost:5173'
      : null,

  /// React Fast Refresh in dev
  reactRefresh: true,
);
</code></pre> <p>The provider sets up Inertia in every isolate. Put it in <code>lib/providers/</code>, so the generated container finds it:</p> lib/providers/inertia_provider.dart<pre><code>import 'package:dox_inertia/dox_inertia.dart';

import '../config/inertia.dart';

class AppInertiaProvider extends InertiaProvider {
  AppInertiaProvider() : super(inertiaConfig);
}
</code></pre>

vite.config.js<pre><code>import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig(({ command }) =&gt; ({
  plugins: [react()],
  // public/ holds the Dox public files, so Vite must not copy it
  publicDir: false,
  base: command === 'build' ? '/build/' : '/',
  server: { origin: 'http://localhost:5173' },
  build: {
    manifest: true,
    outDir: 'public/build',
    rollupOptions: { input: 'resources/js/app.jsx' },
  },
}))
</code></pre> resources/js/app.jsx<pre><code>import { createInertiaApp } from '@inertiajs/react'
import { createRoot } from 'react-dom/client'

createInertiaApp({
  resolve: (name) =&gt; {
    const pages = import.meta.glob('./Pages/**/*.jsx', { eager: true })
    return pages[`./Pages/${name}.jsx`]
  },
  setup({ el, App, props }) {
    createRoot(el).render(&lt;App {...props} /&gt;)
  },
})
</code></pre> <p>A page name like <code>Tasks/Index</code> loads the file <code>resources/js/Pages/Tasks/Index.jsx</code>.</p>

resources/js/Pages/Tasks/Index.jsx<pre><code>import { Head, router, useForm, usePage } from '@inertiajs/react'

export default function Index({ tasks }) {
  const { flash } = usePage()
  const { data, setData, post, processing, errors, reset } = useForm({ title: '' })

  function submit(e) {
    e.preventDefault()
    post('/tasks', { onSuccess: () =&gt; reset() })
  }

  return (
    &lt;main&gt;
      &lt;Head title="Tasks" /&gt;
      {flash.message &amp;&amp; &lt;p className="notice"&gt;{flash.message}&lt;/p&gt;}

      &lt;form onSubmit={submit}&gt;
        &lt;input value={data.title} onChange={(e) =&gt; setData('title', e.target.value)} /&gt;
        &lt;button disabled={processing}&gt;Add&lt;/button&gt;
        {errors.title &amp;&amp; &lt;p className="error"&gt;{errors.title}&lt;/p&gt;}
      &lt;/form&gt;

      &lt;ul&gt;
        {tasks.map((task) =&gt; (
          &lt;li key={task.id}&gt;
            {task.title}
            &lt;button onClick={() =&gt; router.delete(`/tasks/${task.id}`)}&gt;Delete&lt;/button&gt;
          &lt;/li&gt;
        ))}
      &lt;/ul&gt;
    &lt;/main&gt;
  )
}
</code></pre> <p>The <code>tasks</code> prop is the list from the controller. <code>errors.title</code> holds the message of the DTO rule. Links made with <code>&lt;Link&gt;</code> from <code>@inertiajs/react</code> change the page with no full reload.</p>
